    ["Show minimap button"] = "Afficher le bouton de minicarte",
    ["Left-click for a quick set-switcher menu, right-click to open settings, drag to reposition."] = "Clic gauche pour le menu de changement rapide, clic droit pour les réglages, glisser pour déplacer.",
    ["Left-click: switch set"] = "Clic gauche : changer d'ensemble",
    ["Right-click: settings"] = "Clic droit : réglages",
