    -- Changement automatique
    ["Auto-Switch on Stance/Form"] = "Changement automatique selon la posture/forme",
    ["Enable auto-switching"] = "Activer le changement automatique",
    ["Automatically equips a loadout when your stance/form changes (warrior stances, druid forms). Out-of-combat only — if a stance change happens in combat, the swap is deferred until combat ends."] = "Équipe automatiquement un ensemble quand votre posture ou forme change (postures de guerrier, formes de druide). Hors combat uniquement — si le changement survient en combat, l'échange est reporté à la fin du combat.",
    ["Auto-equip on form"] = "Équiper automatiquement selon la forme",
    ["Equip this loadout automatically when the chosen stance/form is activated."] = "Équiper automatiquement cet ensemble quand la posture ou forme choisie est activée.",
    ["Auto-Switch on Dual Spec"] = "Changement automatique selon la double spécialisation",
    ["Enable spec auto-switching"] = "Activer le changement selon la spécialisation",
    ["Automatically equips a loadout when you switch between Spec 1 and Spec 2 (dual spec). Bind each loadout to a spec below. Requires dual spec to be active."] = "Équipe automatiquement un ensemble quand vous passez de la spécialisation 1 à la 2 (double spécialisation). Associez chaque ensemble à une spécialisation ci-dessous. Nécessite la double spécialisation.",
    ["Auto-equip on spec"] = "Équiper automatiquement selon la spécialisation",
    ["Equip this loadout automatically when you switch to this spec."] = "Équiper automatiquement cet ensemble quand vous passez à cette spécialisation.",
    ["None"] = "Aucun",
    ["No Form"] = "Aucune forme",
    ["Form %d"] = "Forme %d",

    -- Barre latérale du personnage
    ["Character Frame Sidebar"] = "Barre latérale du personnage",
    ["Show sidebar on character frame"] = "Afficher la barre latérale sur la fenêtre du personnage",
    ["Attach a quick-access sidebar to the right of the character window. Click a set to select, double-click or button to equip, right-click for context menu."] = "Ajoute une barre d'accès rapide à droite de la fenêtre du personnage. Cliquez sur un ensemble pour le sélectionner, double-cliquez ou utilisez le bouton pour l'équiper, clic droit pour le menu contextuel.",
    ["|cffaaaaaaTip: with the character window open, enable edit mode (Unlock) to drag the sidebar; right-click the purple box to reset its position.|r"] = "|cffaaaaaaAstuce : la fenêtre du personnage ouverte, activez le mode édition (Déverrouiller) pour glisser la barre latérale ; clic droit sur le cadre violet pour réinitialiser sa position.|r",
    ["New Set"] = "Nouvel ensemble",
    ["Left-click: select"] = "Clic gauche : sélectionner",
    ["Double-click / Right-click menu: equip"] = "Double-clic / menu clic droit : équiper",
    ["Change icon..."] = "Changer d'icône...",
    ["Icon for: %s"] = "Icône pour : %s",
    ["Bind to %s"] = "Associer à %s",
    ["'%s' bound to %s."] = "« %s » associé à %s.",
    ["'%s' unbound from spec."] = "« %s » dissocié de la spécialisation.",
    ["Replace: %s"] = "Remplacer : %s",
    ["Remove from set"] = "Retirer de l'ensemble",
    ["Loadout '%s': slot updated."] = "Ensemble « %s » : emplacement mis à jour.",
    ["SlotPicker module is required for editing item slots."] = "Le module SlotPicker est nécessaire pour modifier les emplacements d'objets.",

