    ["Add a slot"] = "Ajouter un emplacement",
    ["Re-adds an ignored slot to this set."] = "Réintègre un emplacement ignoré dans cet ensemble.",
    ["Right-click: remove this slot from the set."] = "Clic droit : retirer cet emplacement de l'ensemble.",
    ["Left-click to pick an item from your bags"] = "Clic gauche pour choisir un objet dans vos sacs",
    ["(equipped)"] = "(équipé)",

    -- Sélecteur d'objets
    ["Slot Picker"] = "Sélecteur d'emplacement",
    ["Enable slot picker"] = "Activer le sélecteur d'emplacement",
    ["|cffaaaaaaRight-click an equipment slot in the character window to see all compatible items from your bags and click one to equip it.|r"] = "|cffaaaaaaFaites un clic droit sur un emplacement d'équipement dans la fenêtre du personnage pour voir tous les objets compatibles de vos sacs, puis cliquez sur l'un d'eux pour l'équiper.|r",
    ["Hover an equipment slot in the Character frame for a compact flyout of compatible bag items, or modifier-click for a larger pinnable picker. Click an item to equip it (out-of-combat)."] = "Survolez un emplacement de la fenêtre du personnage pour obtenir une bande compacte des objets compatibles, ou utilisez la touche de modification pour un sélecteur plus grand que l'on peut épingler. Cliquez sur un objet pour l'équiper (hors combat).",
    ["Flyout on hover"] = "Bande au survol",
    ["Hovering an equipment slot pops out a compact strip of items you can swap in — the paperdoll flyout look. Turn off to use only the modifier-click picker."] = "Survoler un emplacement fait apparaître une bande compacte des objets échangeables — le style des fenêtres volantes du personnage. Désactivez pour n'utiliser que le sélecteur avec touche de modification.",
    ["Activation modifier"] = "Touche d'activation",
    ["Choose which key combination opens the item picker when you click an equipment slot."] = "Choisissez la combinaison de touches qui ouvre le sélecteur lorsque vous cliquez sur un emplacement.",
    ["Shift + Right-click"] = "Maj + clic droit",
    ["Alt + Right-click"] = "Alt + clic droit",
    ["Ctrl + Right-click"] = "Ctrl + clic droit",
    ["Right-click only"] = "Clic droit seul",
    ["Grid columns"] = "Colonnes de la grille",
    ["How many item icons per row in the picker popup."] = "Nombre d'icônes d'objets par ligne dans le sélecteur.",
    ["Items for: %s"] = "Objets pour : %s",
    ["Close automatically on mouse-out"] = "Fermer automatiquement à la sortie de la souris",
    ["The picker closes itself shortly after the mouse leaves it. Drag it once to pin it open until you close it manually."] = "Le sélecteur se ferme peu après que la souris l'a quitté. Faites-le glisser une fois pour l'épingler jusqu'à fermeture manuelle.",
    ["No matching items in your bags."] = "Aucun objet correspondant dans vos sacs.",
    ["Item scanning API not available on this client."] = "L'analyse des objets n'est pas disponible sur ce client.",

