    ["Auto (client language)"] = "Auto (langue du client)",
    ["Choose the language for the VuloClassicUI interface. 'Auto' uses your WoW client's language (German clients see German, all others see English).\n\n|cffaaaaaaRequires /reload to apply.|r"] = "Choisissez la langue de l'interface VuloClassicUI. « Auto » utilise la langue de votre client WoW (les clients allemands voient l'allemand, tous les autres l'anglais).\n\n|cffaaaaaaNécessite /reload pour être appliqué.|r",
    ["Language changed. /reload required to apply the new language to all UI elements."] = "Langue modifiée. /reload nécessaire pour appliquer la nouvelle langue à toute l'interface.",
