    ["Only show while on cooldown"] = "Afficher uniquement pendant la recharge",
    ["Hides ready icons; they reappear when on cooldown."] = "Masque les icônes prêtes ; elles réapparaissent pendant la recharge.",
    ["Show countdown text"] = "Afficher le compte à rebours",
