    ["Apexis Relic memory minigame helper (Ogri'la dailies): record the flashing color sequence, always see what to click next."] = "Aide pour le mini-jeu de mémoire de la relique d'apexis (quotidiennes d'Ogri'la) : notez la séquence de couleurs et voyez toujours sur quoi cliquer ensuite.",
