    ["Click to record this color."] = "Cliquez pour noter cette couleur.",
    ["Hotkey: %s"] = "Raccourci : %s",
    ["LazyVulo is disabled."] = "LazyVulo est désactivé.",
    ["|cffaaaaaaHelper for the Apexis Relic memory minigame (Ogri'la dailies). Record the flashing sequence with the buttons or hotkeys; the first icon is always your next click. Correct clicks are consumed automatically, wrong clicks are restored.|r"] = "|cffaaaaaaAide pour le mini-jeu de mémoire de la relique d'apexis (quotidiennes d'Ogri'la). Notez la séquence clignotante avec les boutons ou les raccourcis ; la première icône est toujours votre prochain clic. Les bons clics sont consommés automatiquement, les mauvais sont rétablis.|r",
    ["|cffaaaaaaOpen manually with /lazyvulo or /lv.|r"] = "|cffaaaaaaOuvrez-le manuellement avec /lazyvulo ou /lv.|r",
    ["Auto-show at the Apexis Relic"] = "Afficher automatiquement à la relique d'apexis",
    ["Opens the window automatically when you start the relic minigame."] = "Ouvre la fenêtre automatiquement quand vous lancez le mini-jeu de la relique.",
