    ["Block group invites from strangers"] = "Bloquer les invitations de groupe des inconnus",
    ["Auto-declines party/raid invites from players who are not in your guild or on your friends list."] = "Refuse automatiquement les invitations de groupe ou de raid venant de joueurs qui ne sont ni dans votre guilde ni dans votre liste d'amis.",
    ["Block trades from strangers"] = "Bloquer les échanges des inconnus",
    ["Auto-closes trade windows opened by players who are not in your guild or on your friends list. Trades you start yourself are not affected."] = "Ferme automatiquement les fenêtres d'échange ouvertes par des joueurs qui ne sont ni dans votre guilde ni dans votre liste d'amis. Les échanges que vous lancez vous-même ne sont pas concernés.",
