    ["|cffff5555Error disabling '%s':|r %s"] = "|cffff5555Erreur à la désactivation de « %s » :|r %s",
    ["Module '%s' disabled. /reload recommended for full effect."] = "Module « %s » désactivé. /reload recommandé pour un effet complet.",
    ["|cffff5555LibSharedMedia-3.0 not found, Media Registry will be skipped.|r"] = "|cffff5555LibSharedMedia-3.0 introuvable, le registre des médias sera ignoré.|r",

    -- Profils
    ["Profiles"] = "Profils",
    ["Manage profiles with different settings. A default profile can be assigned per class and is loaded automatically on login."] = "Gérez des profils avec des réglages différents. Un profil par défaut peut être attribué à chaque classe et se charge automatiquement à la connexion.",
    ["Active Profile"] = "Profil actif",
    ["You are currently using: |cff9b6cff%s|r  (Class: %s)"] = "Vous utilisez actuellement : |cff9b6cff%s|r  (classe : %s)",
    ["Switch Profile"] = "Changer de profil",
    ["Profile for this character"] = "Profil pour ce personnage",
    ["|cffaaaaaaPins a profile to THIS character only. At login it beats the class assignment and the account-wide selection - so every character can keep its own minimap, bars and window settings.|r"] = "|cffaaaaaaFixe un profil à CE personnage uniquement. À la connexion, il l'emporte sur l'attribution par classe et sur la sélection commune au compte — chaque personnage garde ainsi sa propre minicarte, ses barres et ses fenêtres.|r",
    ["This character"] = "Ce personnage",
    ["Create New Profile"] = "Créer un profil",
    ["Name"] = "Nom",
    ["Copy Settings From"] = "Copier les réglages depuis",
    ["- empty profile (defaults) -"] = "- profil vide (valeurs par défaut) -",
    ["- none -"] = "- aucun -",
    ["Create Profile"] = "Créer le profil",
    ["|cffff5555Please enter a name.|r"] = "|cffff5555Veuillez saisir un nom.|r",
    ["|cffff5555Please enter a new name.|r"] = "|cffff5555Veuillez saisir un nouveau nom.|r",
    ["Error."] = "Erreur.",
    ["Share Profile"] = "Partager le profil",
    ["|cffaaaaaaExport the current profile as a text string - as a backup or to share it. Importing always creates a NEW profile and never overwrites anything.|r"] = "|cffaaaaaaExportez le profil actuel sous forme de chaîne de texte — comme sauvegarde ou pour le partager. L'importation crée toujours un NOUVEAU profil et n'écrase jamais rien.|r",
    ["Export as string"] = "Exporter en chaîne",
    ["Import from string"] = "Importer depuis une chaîne",
    ["Copy the profile string (Ctrl+C):"] = "Copiez la chaîne de profil (Ctrl+C) :",
    ["Paste the profile string:"] = "Collez la chaîne de profil :",
    ["This is not a VuloClassicUI profile string."] = "Ceci n'est pas une chaîne de profil VuloClassicUI.",
    ["The profile string is damaged."] = "La chaîne de profil est endommagée.",
    ["Profile '%s' imported. Activate it via 'Switch Profile'."] = "Profil « %s » importé. Activez-le via « Changer de profil ».",
    ["Manage Profiles"] = "Gérer les profils",
    ["Delete..."] = "Supprimer...",
    ["Reset to defaults..."] = "Réinitialiser aux valeurs par défaut...",
    ["Delete profile '%s'? This cannot be undone."] = "Supprimer le profil « %s » ? Cette action est irréversible.",
    ["Reset profile '%s' to the default settings? This cannot be undone."] = "Réinitialiser le profil « %s » aux réglages par défaut ? Cette action est irréversible.",
    ["Profile changed. Reload the UI now so every module picks it up?"] = "Profil modifié. Recharger l'interface maintenant pour que tous les modules en tiennent compte ?",
    ["|cffff5555Profile '%s' could not be loaded:|r %s"] = "|cffff5555Le profil « %s » n'a pas pu être chargé :|r %s",
    ["Rename to"] = "Renommer en",
    ["Rename"] = "Renommer",
    ["|cffff5555Default profile cannot be deleted.|r"] = "|cffff5555Le profil par défaut ne peut pas être supprimé.|r",
    ["Apply to Active Class"] = "Appliquer à la classe actuelle",
    ["Sets the current profile as the default for %s."] = "Définit le profil actuel comme profil par défaut pour %s.",
    ["'%s' is now the default profile for %s."] = "« %s » est désormais le profil par défaut pour %s.",
    ["Per-class profile (quick setup)"] = "Profil par classe (installation rapide)",
    ["|cffaaaaaaOne click: makes a profile named after your class (copied from the current one) and loads it for this class automatically. Run it once on each character — every class then keeps its own cooldown bars, frames and settings.|r"] = "|cffaaaaaaUn clic : crée un profil portant le nom de votre classe (copié depuis l'actuel) et le charge automatiquement pour cette classe. À faire une fois sur chaque personnage — chaque classe garde alors ses propres barres de recharge, fenêtres et réglages.|r",
    ["Set up a %s profile"] = "Créer un profil %s",
    ["'%s' is now the %s profile. |cffffff00/reload|r to apply."] = "« %s » est désormais le profil %s. |cffffff00/reload|r pour appliquer.",
    ["Profile Assignment per Class"] = "Attribution de profil par classe",
    ["Choose a default profile for each class. When logging in with a character of that class, the profile will be loaded automatically."] = "Choisissez un profil par défaut pour chaque classe. À la connexion d'un personnage de cette classe, le profil sera chargé automatiquement.",
    ["Settings migrated to profile system (all settings are in profile '%s')."] = "Réglages migrés vers le système de profils (tous les réglages se trouvent dans le profil « %s »).",
    ["|cffff5555Profile '%s' does not exist.|r"] = "|cffff5555Le profil « %s » n'existe pas.|r",
    ["Profile '%s' created%s."] = "Profil « %s » créé%s.",
    [" (copy of '%s')"] = " (copie de « %s »)",
    ["Name cannot be empty."] = "Le nom ne peut pas être vide.",
    ["Profile already exists."] = "Ce profil existe déjà.",
    ["Default profile cannot be deleted."] = "Le profil par défaut ne peut pas être supprimé.",
    ["Profile does not exist."] = "Ce profil n'existe pas.",
    ["Active profile deleted. Default loaded. /reload recommended."] = "Profil actif supprimé. Profil par défaut chargé. /reload recommandé.",
    ["Profile '%s' deleted."] = "Profil « %s » supprimé.",
    ["Default profile cannot be renamed."] = "Le profil par défaut ne peut pas être renommé.",
    ["New name already exists."] = "Ce nouveau nom existe déjà.",
    ["Profile '%s' renamed to '%s'."] = "Profil « %s » renommé en « %s ».",
    ["Profile '%s' loaded. |cffffff00/reload|r recommended so all modules use the new settings."] = "Profil « %s » chargé. |cffffff00/reload|r recommandé pour que tous les modules utilisent les nouveaux réglages.",
    ["Settings imported from VuloFontBars."] = "Réglages importés depuis VuloFontBars.",
    ["Settings imported from ArenaEnemyEdit."] = "Réglages importés depuis ArenaEnemyEdit.",
    ["Settings imported from BetterBlizzQueue."] = "Réglages importés depuis BetterBlizzQueue.",
    ["Settings imported from idTip."] = "Réglages importés depuis idTip.",
    ["|cffff5555Profile module not loaded.|r"] = "|cffff5555Module de profils non chargé.|r",

