    -- Réglages globaux
    ["Global Settings"] = "Réglages généraux",
    ["Global UI settings + profile management."] = "Réglages généraux de l'interface et gestion des profils.",
    ["UI Scale"] = "Échelle de l'interface",
    ["Manual UI scaling. 0.65 is smaller, 1.0 is default."] = "Échelle manuelle de l'interface. 0,65 est plus petit, 1,0 est la valeur par défaut.",
    ["Pixel Perfect"] = "Pixel perfect",
    ["UI Scale = %.4f (pixel perfect)"] = "Échelle de l'interface = %.4f (pixel perfect)",
    ["1080p Scale"] = "Échelle 1080p",
    ["UI Scale = 0.7111 (1080p)"] = "Échelle de l'interface = 0,7111 (1080p)",
    ["1440p Scale"] = "Échelle 1440p",
    ["UI Scale = 0.5333 (1440p)"] = "Échelle de l'interface = 0,5333 (1440p)",
    ["Max Camera Distance"] = "Distance maximale de la caméra",
    ["Maximum camera distance (CVar cameraDistanceMaxZoomFactor)."] = "Distance maximale de la caméra (CVar cameraDistanceMaxZoomFactor).",
    ["Show Minimap Button"] = "Afficher le bouton de minicarte",
    ["Toggle the VuloClassicUI button on the minimap."] = "Affiche ou masque le bouton VuloClassicUI sur la minicarte.",
    ["Performance Display"] = "Affichage des performances",
    ["Show CPU Usage in Header"] = "Afficher l'usage processeur dans l'en-tête",
    ["Shows total CPU usage of all active addons (plus VuloClassicUI's own share) at the top of the config header.\n\n|cffaaaaaaRequires /reload after toggling.\n\nNote: Enables WoW's scriptProfile CVar, which costs ~3-5% performance — that's the price for WoW collecting this data at all.|r"] = "Affiche l'usage processeur total de tous les add-ons actifs (et la part propre de VuloClassicUI) en haut de l'en-tête des réglages.\n\n|cffaaaaaaNécessite un /reload après la bascule.\n\nRemarque : active la CVar scriptProfile de WoW, qui coûte environ 3 à 5 % en performances — c'est le prix pour que WoW collecte ces données.|r",
    ["Script profiling changed. /reload required for the CPU display to update."] = "Profilage des scripts modifié. /reload nécessaire pour que l'affichage processeur se mette à jour.",
    ["Reload now"] = "Recharger maintenant",
    ["Later"] = "Plus tard",
    ["Shows a button on the minimap to quickly open VuloClassicUI. Shift+drag moves the button."] = "Affiche un bouton sur la minicarte pour ouvrir rapidement VuloClassicUI. Maj + glisser déplace le bouton.",
    ["UI is not loaded yet."] = "L'interface n'est pas encore chargée.",
    ["|cffffffffLeft click:|r Open options"] = "|cffffffffClic gauche :|r ouvrir les options",
    ["|cffffffffRight click:|r Quick module selection"] = "|cffffffffClic droit :|r sélection rapide de module",
    ["|cffffffffShift+drag:|r Move button"] = "|cffffffffMaj + glisser :|r déplacer le bouton",
    ["Open Options"] = "Ouvrir les options",
    ["Show button on minimap"] = "Afficher le bouton sur la minicarte",
    ["If off, the button is completely hidden."] = "Si désactivé, le bouton est entièrement masqué.",
    ["Distance from center"] = "Distance depuis le centre",
    ["Angle (degrees)"] = "Angle (degrés)",
    ["Tip: You can also move the button directly on the minimap — hold Shift and drag it to the desired position."] = "Astuce : vous pouvez aussi déplacer le bouton directement sur la minicarte — maintenez Maj et faites-le glisser à l'endroit voulu.",

    -- Barres de police
    ["Font Bars"] = "Polices des barres",
    ["Smaller font sizes for Player/Target/Pet Health & Mana bars, optionally hide TargetFrameBackground."] = "Polices plus petites pour les barres de vie et de mana du joueur, de la cible et du familier, avec masquage facultatif du fond de la fenêtre de cible.",
    ["Health Bar Text"] = "Texte des barres de vie",
    ["Font size on health bars (Player/Target/Pet)."] = "Taille de police sur les barres de vie (joueur, cible, familier).",
    ["Power Bar Text"] = "Texte des barres de ressource",
    ["Font size on mana/power bars."] = "Taille de police sur les barres de mana et de ressource.",
    ["Pet Combat Feedback Text"] = "Texte de combat du familier",
    ["Font size for 'Damage', 'Dodge', 'Miss' on the pet."] = "Taille de police pour « Dégâts », « Esquive », « Manqué » sur le familier.",
    ["Only affect Player/Target/Pet bars"] = "N'affecter que les barres du joueur, de la cible et du familier",
    ["If off: all TextStatusBars in the UI are overridden with the sizes above (may interfere with other addons)."] = "Si désactivé : toutes les barres de texte de l'interface reçoivent les tailles ci-dessus (peut interférer avec d'autres add-ons).",
    ["Hide TargetFrame background"] = "Masquer le fond de la fenêtre de cible",
    ["Permanently hides the dark background element of the TargetFrame."] = "Masque définitivement l'élément de fond sombre de la fenêtre de cible.",

    -- Fenêtre de cible
    ["Target Frame"] = "Fenêtre de cible",
    ["|cffaaaaaaAdds the modern Target/Focus frame extras the default Anniversary UI is missing - all cosmetic, no taint.|r"] = "|cffaaaaaaAjoute aux fenêtres de cible et de focus les compléments modernes absents de l'interface Anniversaire — purement cosmétique, sans corruption du code protégé.|r",
    ["Numeric threat %"] = "Menace en pourcentage",
    ["Shows your threat percentage on the target (and focus) above the frame, coloured by threat status."] = "Affiche votre pourcentage de menace sur la cible (et le focus) au-dessus de la fenêtre, coloré selon l'état de menace.",
    ["Threat glow"] = "Lueur de menace",
    ["Glows the target (and focus) frame in yellow/orange/red as your threat rises."] = "Fait luire la fenêtre de cible (et de focus) en jaune, orange puis rouge à mesure que votre menace augmente.",
    ["Rare-Elite border"] = "Bordure rare-élite",
    ["Shows the winged silver-dragon Rare-Elite border on rare-elite mobs."] = "Affiche la bordure rare-élite au dragon argenté ailé sur les créatures rare-élite.",
    ["Class icon on player targets"] = "Icône de classe sur les cibles joueurs",
    ["Shows the target's class crest on the frame when you target a player."] = "Affiche l'emblème de classe de la cible sur la fenêtre quand vous ciblez un joueur.",
    ["Also apply to the Focus frame"] = "Appliquer aussi à la fenêtre de focus",
    ["Health"] = "Points de vie",
    ["Show real NPC health"] = "Afficher les points de vie réels des PNJ",
    ["Shows the true health value on NPCs instead of the obfuscated percentage (enemy players stay %)."] = "Affiche la valeur réelle des points de vie des PNJ au lieu du pourcentage masqué (les joueurs ennemis restent en %).",

    -- Barre d'incantation
    ["Player Castbar"] = "Barre d'incantation du joueur",
    ["Player castbar with two modes: Original (Blizzard bar extended) or Custom castbar (VUI style)."] = "Barre d'incantation du joueur avec deux modes : Originale (barre de Blizzard enrichie) ou Personnalisée (style VUI).",
    ["|cffffffffCASTBAR|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffffBARRE D'INCANTATION|r\n|cffaaaaaaGlisser ou touches fléchées|r",
    ["Castbar position: x=%.0f, y=%.0f"] = "Position de la barre d'incantation : x=%.0f, y=%.0f",
    ["|cff9b6cffMind Flay|r"] = "|cff9b6cffFouet mental|r",
    ["Castbar mover active. |cff9b6cffDrag purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "Déplacement de la barre d'incantation actif. |cff9b6cffGlissez le cadre violet|r ou utilisez les |cff9b6cfftouches fléchées|r (MAJ = 5 px). Cliquez de nouveau sur « Déverrouiller / tester » pour terminer.",
    ["Castbar mover disabled."] = "Déplacement de la barre d'incantation désactivé.",
    ["Castbar Variant"] = "Variante de barre d'incantation",
    ["Switch between Original (Blizzard bar extended) and Custom castbar (VUI style with icon, spell name below bar)."] = "Basculez entre Originale (barre de Blizzard enrichie) et Personnalisée (style VUI avec icône et nom du sort sous la barre).",
    ["Original (Blizzard bar extended)"] = "Originale (barre de Blizzard enrichie)",
    ["Custom Castbar (VUI style)"] = "Barre personnalisée (style VUI)",
    ["Castbar mode switched to |cff9b6cffOriginal|r. |cffffff00/reload|r recommended so the default bar works normally again."] = "Mode de barre d'incantation basculé sur |cff9b6cffOriginale|r. |cffffff00/reload|r recommandé pour que la barre par défaut refonctionne normalement.",
    ["Castbar mode switched to |cff9b6cffVUI Style|r."] = "Mode de barre d'incantation basculé sur |cff9b6cffstyle VUI|r.",
    ["|cffaaaaaaMode switch: A /reload may be required after switching so the default bar works normally again.|r"] = "|cffaaaaaaChangement de mode : un /reload peut être nécessaire après la bascule pour que la barre par défaut refonctionne normalement.|r",
    ["Show spell name"] = "Afficher le nom du sort",
    ["Show cast timer"] = "Afficher le minuteur d'incantation",
    ["Show channel ticks"] = "Afficher les paliers de canalisation",
    ["Shows vertical lines at tick points (Mind Flay, Drain Soul, Hellfire, etc.)"] = "Affiche des lignes verticales aux paliers (Fouet mental, Drain d'âme, Feu infernal, etc.)",
    ["Show clip window"] = "Afficher la fenêtre de coupure",
    ["Shades your latency at the end of the bar: on channels the moment to recast without losing the last tick, on casts the spell-queue window where the next cast can already be pressed."] = "Ombre votre latence en fin de barre : sur les canalisations, le moment pour relancer sans perdre le dernier palier ; sur les incantations, la fenêtre de file d'attente où le sort suivant peut déjà être lancé.",
    ["Timer format"] = "Format du minuteur",
    ["Remaining / total (1.5 / 2.0)"] = "Restant / total (1,5 / 2,0)",
    ["Remaining only (1.5)"] = "Restant seulement (1,5)",
    ["Whole seconds (2)"] = "Secondes entières (2)",
    ["Show pushback"] = "Afficher le retard d'incantation",
    ["Briefly shows the time lost to spell pushback in red above the bar."] = "Affiche brièvement en rouge, au-dessus de la barre, le temps perdu par retard d'incantation.",
    ["Merge crafting casts"] = "Regrouper les fabrications",
    ["When crafting several items in a row the bar shows a counter like 3/20 instead of single casts."] = "Lors de la fabrication de plusieurs objets d'affilée, la barre affiche un compteur du type 3/20 au lieu d'incantations séparées.",
    ["Fill color"] = "Couleur de remplissage",
    ["Bar textures = the classic yellow/green art. Accent or class color tint a neutral bar instead."] = "Les textures de barre correspondent au rendu classique jaune/vert. La couleur d'accent ou de classe teinte plutôt une barre neutre.",
    ["Bar textures (yellow/green)"] = "Textures de barre (jaune/vert)",
    ["Accent color"] = "Couleur d'accent",
    ["VUI Style: Position & Size"] = "Style VUI : position et taille",
    ["Unlock / Test"] = "Déverrouiller / tester",
    ["Center Position"] = "Centrer la position",
    ["|cffaaaaaaTip: Hold |cffffffffSHIFT|r and drag the castbar with the left mouse button during a cast to move it. Or use 'Unlock / Test' for a permanent test bar for positioning.|r"] = "|cffaaaaaaAstuce : maintenez |cffffffffMAJ|r et glissez la barre d'incantation avec le bouton gauche pendant une incantation pour la déplacer. Ou utilisez « Déverrouiller / tester » pour une barre de test permanente.|r",
    ["Show icon"] = "Afficher l'icône",
    ["Icon Size"] = "Taille de l'icône",
    ["Icon X Offset"] = "Décalage X de l'icône",
    ["Icon Y Offset"] = "Décalage Y de l'icône",
    ["Moves the icon horizontally. Negative = left, positive = right."] = "Déplace l'icône horizontalement. Négatif = gauche, positif = droite.",
    ["Moves the icon vertically. Positive = up, negative = down."] = "Déplace l'icône verticalement. Positif = haut, négatif = bas.",
    ["Test only available in 'Custom Castbar' mode."] = "Le test n'est disponible qu'en mode « Barre personnalisée ».",

    -- Impulsion de recharge
    ["Cooldown Pulse"] = "Impulsion de recharge",
    ["Shows the icon of an expired cooldown as a brief pulsing animation in the screen center (based on Doom_CooldownPulse)."] = "Affiche l'icône d'une recharge terminée sous forme d'une brève animation pulsée au centre de l'écran (d'après Doom_CooldownPulse).",
    ["Test Spell"] = "Sort de test",
    ["Cooldown Pulse position reset."] = "Position de l'impulsion réinitialisée.",
    ["Test Pulse"] = "Tester l'impulsion",
    ["Plays a test animation."] = "Joue une animation de test.",
    ["Reset Position"] = "Réinitialiser la position",
    ["Max Opacity"] = "Opacité maximale",
    ["Animation Scale"] = "Échelle de l'animation",
    ["Fade-In Time (s)"] = "Durée d'apparition (s)",
    ["Hold Time (s)"] = "Durée d'affichage (s)",
    ["Fade-Out Time (s)"] = "Durée de disparition (s)",
    ["Show Before Available (s)"] = "Afficher avant disponibilité (s)",
    ["Triggers the animation X seconds BEFORE the cooldown expires. 0 = exactly at cooldown end."] = "Déclenche l'animation X secondes AVANT la fin de la recharge. 0 = exactement à la fin.",
    ["Spell Filter"] = "Filtre de sorts",
    ["Show spell names"] = "Afficher les noms de sorts",
    ["Shows the name of the spell under the icon."] = "Affiche le nom du sort sous l'icône.",
    ["Invert filter (whitelist instead of blacklist)"] = "Inverser le filtre (liste blanche au lieu de liste noire)",
    ["Off: List = ignored spells. On: List = show ONLY these spells."] = "Désactivé : la liste contient les sorts ignorés. Activé : la liste contient les SEULS sorts affichés.",
    ["Spell List (comma-separated)"] = "Liste de sorts (séparés par des virgules)",
    ["Spell names exactly as in-game, comma-separated. Spell IDs also work."] = "Noms de sorts exactement comme en jeu, séparés par des virgules. Les identifiants fonctionnent aussi.",

    -- Fenêtres d'arène
    ["Arena Frames"] = "Fenêtres d'arène",
    ["Enhances the Arena enemy frames: move/scale, class colors, class icons, PvP trinket CD, DR tracking, castbar, drag&drop layout."] = "Améliore les fenêtres des ennemis d'arène : déplacement et échelle, couleurs et icônes de classe, recharge du bijou JcJ, suivi des réductions, barre d'incantation, disposition par glisser-déposer.",
    ["|cffff5555ArenaFrames submodule error:|r %s"] = "|cffff5555Erreur du sous-module des fenêtres d'arène :|r %s",
    ["|cffff5555Arena submodule OnEnable error:|r %s"] = "|cffff5555Erreur à l'activation du sous-module d'arène :|r %s",
    ["Layout"] = "Disposition",
    ["Class Color"] = "Couleur de classe",
    ["PvP Trinket"] = "Bijou JcJ",
    ["DR Tracker"] = "Suivi des réductions",
    ["Castbar"] = "Barre d'incantation",
    ["ArenaPlayer"] = "JoueurArène",
    ["Reset position"] = "Réinitialiser la position",
    ["Position reset."] = "Position réinitialisée.",
    ["In unlock mode a purple overlay appears above the frames. Click + drag to move, mouse wheel to scale."] = "En mode déverrouillage, un calque violet apparaît au-dessus des fenêtres. Cliquez et glissez pour déplacer, molette pour l'échelle.",
    ["Layout (Order)"] = "Disposition (ordre)",
    ["Order of the arena frames. Use up/down to move slots 1-5."] = "Ordre des fenêtres d'arène. Utilisez haut/bas pour déplacer les emplacements 1 à 5.",
    ["|cff9b6cff%d.|r  Arena Slot %d"] = "|cff9b6cff%d.|r  Emplacement d'arène %d",
    ["Move up"] = "Monter",
    ["Move down"] = "Descendre",
    ["Spacing between frames"] = "Espacement entre les fenêtres",
    ["Grow direction"] = "Sens de croissance",
    ["Downward"] = "Vers le bas",
    ["Upward"] = "Vers le haut",
    ["Reset order"] = "Réinitialiser l'ordre",
    ["Class Visuals"] = "Rendu des classes",
    ["Class-colored health bars"] = "Barres de vie aux couleurs de classe",
    ["Colors the health bar in the player's class color."] = "Colore la barre de vie selon la couleur de classe du joueur.",
    ["Class-colored name"] = "Nom aux couleurs de classe",
    ["Class icon instead of portrait"] = "Icône de classe au lieu du portrait",
    ["Replaces the 3D portrait with a class symbol."] = "Remplace le portrait 3D par un symbole de classe.",
    ["PvP Trinket Tracker"] = "Suivi du bijou JcJ",
    ["Show PvP trinket cooldown"] = "Afficher la recharge du bijou JcJ",
    ["Shows an icon with cooldown spiral next to the arena frame when the opponent used their PvP trinket."] = "Affiche une icône avec spirale de recharge à côté de la fenêtre d'arène quand l'adversaire a utilisé son bijou JcJ.",
    ["Icon size"] = "Taille de l'icône",
    ["Left of frame"] = "À gauche de la fenêtre",
    ["Right of frame"] = "À droite de la fenêtre",
    ["Offset X"] = "Décalage X",
    ["Offset Y"] = "Décalage Y",
    ["Diminishing Returns Tracker"] = "Suivi des réductions d'effet",
    ["Shows icons next to each arena frame for active DR categories (Stun, Fear, Polymorph etc.) with color indicator: |cff00ff00green|r = full, |cffffff00yellow|r = 1/2, |cffff8000orange|r = 1/4, |cffff0000red|r = immune."] = "Affiche à côté de chaque fenêtre d'arène des icônes pour les catégories de réduction actives (étourdissement, peur, métamorphose, etc.) avec un indicateur de couleur : |cff00ff00vert|r = plein, |cffffff00jaune|r = 1/2, |cffff8000orange|r = 1/4, |cffff0000rouge|r = immunisé.",
    ["Enable DR tracking"] = "Activer le suivi des réductions",
    ["INTERRUPTED"] = "INTERROMPU",
    ["Castbar for arena opponents"] = "Barre d'incantation des adversaires d'arène",
    ["Shows a castbar below the frame when the opponent casts or channels."] = "Affiche une barre d'incantation sous la fenêtre quand l'adversaire lance ou canalise un sort.",

    -- Confort de jeu : actions automatiques
    ["Collection of simple quality-of-life toggles: auto-accept (quest, res, summon), auto-sell, repair, hide UI spam, text sizes."] = "Ensemble d'options de confort simples : acceptation automatique (quête, résurrection, invocation), vente automatique, réparation, masquage des messages superflus, tailles de texte.",
    ["Auto-sold: %d items, +%s"] = "Vendu automatiquement : %d objets, +%s",
    ["Auto-sold: %d items."] = "Vendu automatiquement : %d objets.",
    ["Repair exceeds gold (%d < %d)."] = "La réparation dépasse votre or (%d < %d).",
    ["Auto-repaired (%dg %ds)."] = "Réparé automatiquement (%d po %d pa).",
    ["MAX"] = "MAX",
    ["General - Auto Actions"] = "Général — actions automatiques",
    ["|cffaaaaaaSimple on/off switches for common QoL actions. Take effect immediately, no /reload needed.|r"] = "|cffaaaaaaInterrupteurs simples pour les actions de confort courantes. Effet immédiat, aucun /reload nécessaire.|r",
    ["Auto-accept quests"] = "Accepter les quêtes automatiquement",
    ["Automatically accepts quests when clicking an NPC."] = "Accepte automatiquement les quêtes quand vous cliquez sur un PNJ.",
    ["Auto-turn in quests"] = "Rendre les quêtes automatiquement",
    ["Automatically completes finished quests. Waits for user choice on multi-reward quests (no auto-pick)."] = "Termine automatiquement les quêtes achevées. Attend votre choix pour les quêtes à plusieurs récompenses (aucune sélection automatique).",
    ["Auto-accept resurrect"] = "Accepter les résurrections automatiquement",
    ["Automatically clicks 'Accept' on resurrect popups (not in combat)."] = "Clique automatiquement sur « Accepter » lors des fenêtres de résurrection (hors combat).",
    ["Auto-accept summon"] = "Accepter les invocations automatiquement",
    ["Automatically clicks 'Accept' on warlock/stone summon popups."] = "Clique automatiquement sur « Accepter » lors des invocations de démoniste ou de pierre.",
    ["Auto-release spirit in PvP/Arena"] = "Libérer l'esprit automatiquement en JcJ / arène",
    ["Releases instantly on death in BG or arena."] = "Libère instantanément à la mort en champ de bataille ou en arène.",
    ["Auto-sell junk (grey)"] = "Vendre la camelote automatiquement (gris)",
    ["Sells all grey items when opening a vendor. Earnings shown in chat."] = "Vend tous les objets gris à l'ouverture d'un vendeur. Le gain est affiché dans la discussion.",
    ["Auto-repair"] = "Réparation automatique",
    ["Repairs entire equipment at the vendor if gold is sufficient."] = "Répare tout l'équipement chez le vendeur si l'or est suffisant.",
    ["Stack-split popup: MAX button"] = "Fenêtre de quantité : bouton MAX",
    ["Adds a 'MAX' button to the quantity popup. Click = buy full stack (at vendor) or split completely (for bag items)."] = "Ajoute un bouton « MAX » à la fenêtre de quantité. Un clic achète la pile entière (chez un vendeur) ou sépare tout (pour les objets des sacs).",
    ["Stack-split popup: VuloUI look"] = "Fenêtre de quantité : style VuloUI",
    ["Restyles the quantity popup (stack buying/splitting) to match the addon look: dark panel, clean buttons and arrows. Turning this off needs a /reload."] = "Habille la fenêtre de quantité (achat et séparation de piles) dans le style de l'add-on : panneau sombre, boutons et flèches épurés. La désactiver nécessite un /reload.",
    ["Hide UI error messages"] = "Masquer les messages d'erreur de l'interface",
    ["Hides the red error messages in the screen center."] = "Masque les messages d'erreur rouges au centre de l'écran.",
    ["Hide zone text"] = "Masquer le nom de zone",
    ["Hides the large zone name when entering new areas."] = "Masque le grand nom de zone à l'entrée dans une nouvelle région.",
    ["Hide level numbers on portrait"] = "Masquer le niveau sur le portrait",
    ["Hides the level display on the Player/Target/Pet portrait."] = "Masque l'affichage du niveau sur le portrait du joueur, de la cible et du familier.",
    ["Hide keybind text on action buttons"] = "Masquer les raccourcis sur les boutons d'action",
    ["Hides the small key labels (1, F1, etc.) on the action buttons."] = "Masque les petites étiquettes de touche (1, F1, etc.) sur les boutons d'action.",
    ["Hide macro/spell names on action buttons"] = "Masquer les noms de macro et de sort sur les boutons d'action",
    ["Hides the text labels under the action buttons."] = "Masque les étiquettes de texte sous les boutons d'action.",
    ["Hide stack/charge numbers on action buttons"] = "Masquer les compteurs sur les boutons d'action",
    ["Hides the small boxes with numbers at the top right (item stacks, charges, cooldown seconds for long CDs)."] = "Masque les petits encadrés chiffrés en haut à droite (piles d'objets, charges, secondes restantes pour les longues recharges).",
    ["Hide raid group labels"] = "Masquer les libellés de groupe de raid",
    ["Hides the 'Group 1'/'Group 2' labels above the compact raid frames."] = "Masque les libellés « Groupe 1 » / « Groupe 2 » au-dessus des fenêtres de raid compactes.",
    ["Mail Text Size"] = "Taille du texte du courrier",
    ["Font size in mail body (opened + sent mail)."] = "Taille de police dans le corps du courrier (courrier ouvert et envoyé).",
    ["Quest Text Size"] = "Taille du texte des quêtes",
    ["Font size in quest descriptions + quest log."] = "Taille de police dans les descriptions de quête et le journal.",
    ["Book Text Size"] = "Taille du texte des livres",
    ["Font size in readable books and letters from item text."] = "Taille de police dans les livres et lettres lisibles issus du texte d'objet.",

    -- Minuteur de file d'attente
    ["Queue Timer"] = "Minuteur de file d'attente",
    ["Shows a countdown on the PvP/PvE queue pop dialog. Optional sound warning at 5 seconds."] = "Affiche un compte à rebours sur la fenêtre d'acceptation de file JcJ / JcE. Avertissement sonore facultatif à 5 secondes.",
    ["Queue expires in"] = "La file expire dans",
    ["|cff00c0ffQueueTimer:|r "] = "|cff00c0ffMinuteur de file :|r ",
    ["Dungeon queue popped instantly!"] = "File de donjon acceptée instantanément !",
    ["Dungeon queue popped after %s"] = "File de donjon acceptée après %s",
    ["Dungeon queue popped."] = "File de donjon acceptée.",
    ["Queue popped instantly!"] = "File acceptée instantanément !",
    ["Queue popped after %s"] = "File acceptée après %s",
    ["Sound on queue pop"] = "Son à l'acceptation de la file",
    ["Plays a sound as soon as the queue pops."] = "Joue un son dès que la file est prête.",
    ["5-second warning"] = "Avertissement à 5 secondes",
    ["Plays 3 quick sounds when only 5 seconds remain to accept."] = "Joue 3 sons brefs quand il ne reste que 5 secondes pour accepter.",
    ["Hide other timers (e.g. BigWigs)"] = "Masquer les autres minuteurs (p. ex. BigWigs)",
    ["Hides foreign StatusBars on the LFG ready popup so only our timer is visible."] = "Masque les barres d'état étrangères sur la fenêtre de confirmation du recherche de groupe, afin que seul notre minuteur reste visible.",

    -- Identifiants dans les infobulles
    ["Tooltip IDs"] = "Identifiants dans les infobulles",
    ["Shows SpellID, ItemID, NPC ID and many other IDs in tooltips (based on idTip by silverwind)."] = "Affiche l'identifiant de sort, d'objet, de PNJ et bien d'autres dans les infobulles (d'après idTip de silverwind).",
    ["|cff9b6cffTalents:|r "] = "|cff9b6cffTalents :|r ",
    ["|cff9b6cffiLvL:|r %d"] = "|cff9b6cffNiv. obj. :|r %d",
    ["  |cff888888(off by default)|r"] = "  |cff888888(désactivé par défaut)|r",
    ["Shows %s in tooltips."] = "Affiche %s dans les infobulles.",
    ["Shows additional ID lines in tooltips, e.g. spell, item or NPC IDs."] = "Affiche des lignes d'identifiants supplémentaires dans les infobulles, par exemple pour les sorts, objets ou PNJ.",
    ["Quick Select"] = "Sélection rapide",
    ["All on"] = "Tout activer",
    ["All off"] = "Tout désactiver",
    ["Defaults"] = "Valeurs par défaut",
    ["Player Tooltip (Inspect-based)"] = "Infobulle de joueur (par inspection)",
    ["|cffaaaaaaWhen you hover over a player, their average iLvL + talent distribution (e.g. 14/0/47) is shown in the tooltip. Data is cached 60s per player, inspect throttle 1/s.|r"] = "|cffaaaaaaEn survolant un joueur, son niveau d'objet moyen et sa répartition de talents (p. ex. 14/0/47) s'affichent dans l'infobulle. Les données sont conservées 60 s par joueur, avec une inspection par seconde au maximum.|r",
    ["Show average iLvL"] = "Afficher le niveau d'objet moyen",
    ["Show talent distribution (e.g. 14/0/47)"] = "Afficher la répartition de talents (p. ex. 14/0/47)",
    ["ID Types"] = "Types d'identifiants",

    -- Achat automatique
    ["Auto Item Buy"] = "Achat automatique d'objets",
    ["Automatically buys configured items at configured vendors. Shift when opening the merchant window = emergency stop."] = "Achète automatiquement les objets configurés chez les vendeurs configurés. Maj à l'ouverture de la fenêtre du marchand = arrêt d'urgence.",
    ["|cffffd200[AutoItemBuy]|r "] = "|cffffd200[Achat auto]|r ",
    ["Buying: "] = "Achat : ",
    ["Close merchant window after purchase"] = "Fermer la fenêtre du marchand après l'achat",
    ["Closes the merchant window automatically ~0.2s after purchase."] = "Ferme la fenêtre du marchand environ 0,2 s après l'achat.",
    ["Chat message on each purchase"] = "Message dans la discussion à chaque achat",
    ["|cffaaaaaaTip: Hold SHIFT when opening the merchant window to skip automatic purchase once.|r"] = "|cffaaaaaaAstuce : maintenez Maj à l'ouverture de la fenêtre du marchand pour ignorer l'achat automatique une fois.|r",
    ["Add Vendor"] = "Ajouter un vendeur",
    ["Vendor Name"] = "Nom du vendeur",
    ["Add"] = "Ajouter",
    ["|cffff5555Please enter a vendor name.|r"] = "|cffff5555Veuillez saisir un nom de vendeur.|r",
    ["|cffff5555Vendor '%s' already exists.|r"] = "|cffff5555Le vendeur « %s » existe déjà.|r",
    ["Vendor '%s' added."] = "Vendeur « %s » ajouté.",
    ["Manage Vendors"] = "Gérer les vendeurs",
    ["|cffaaaaaaNo vendors added yet. Add a vendor above, then select it here to configure items.|r"] = "|cffaaaaaaAucun vendeur ajouté pour l'instant. Ajoutez-en un ci-dessus, puis sélectionnez-le ici pour configurer les objets.|r",
    ["Currently selected vendor"] = "Vendeur actuellement sélectionné",
    ["Delete this vendor"] = "Supprimer ce vendeur",
    ["Vendor '%s' removed."] = "Vendeur « %s » supprimé.",
    ["Items at '%s'"] = "Objets chez « %s »",
    ["Item name (exactly as in-game)"] = "Nom de l'objet (exactement comme en jeu)",
    ["|cffff5555Please enter an item name.|r"] = "|cffff5555Veuillez saisir un nom d'objet.|r",
    ["Item '%s' added at vendor '%s'."] = "Objet « %s » ajouté chez le vendeur « %s ».",
    ["|cffaaaaaaItem names must match the in-game name exactly (including case and special characters).|r"] = "|cffaaaaaaLes noms d'objets doivent correspondre exactement au nom en jeu (majuscules et caractères spéciaux compris).|r",
    ["|cffaaaaaaNo items configured. Add items above that should be bought automatically at this vendor.|r"] = "|cffaaaaaaAucun objet configuré. Ajoutez ci-dessus les objets à acheter automatiquement chez ce vendeur.|r",
    ["Remove"] = "Retirer",
    ["Item '%s' removed."] = "Objet « %s » retiré.",

    -- Correctif d'inspection
    ["Inspect Fix"] = "Correctif d'inspection",
    ["Inspect state manually reset. Try again now."] = "État d'inspection réinitialisé manuellement. Réessayez maintenant.",
    ["|cffffff00[VuloClassicUI]|r Inspect state reset."] = "|cffffff00[VuloClassicUI]|r État d'inspection réinitialisé.",
    ["Auto-reset on timeout"] = "Réinitialisation automatique après expiration",
    ["If no response from the server comes after X seconds, the pending inspect state is automatically reset — so the next inspect attempt works again."] = "Si le serveur ne répond pas après X secondes, l'inspection en attente est automatiquement réinitialisée — la tentative suivante fonctionne alors de nouveau.",
    ["How long to wait for INSPECT_READY before auto-reset kicks in. 5 seconds is the new default for Anniversary — fast enough to recover quickly."] = "Durée d'attente d'INSPECT_READY avant la réinitialisation automatique. 5 secondes est la nouvelle valeur par défaut sur Anniversaire — assez court pour récupérer rapidement.",
    ["|cffaaaaaaSlash commands: /inspectreset (force-reset), /inspectstate (debug info in chat)|r"] = "|cffaaaaaaCommandes : /inspectreset (réinitialisation forcée), /inspectstate (infos de débogage dans la discussion)|r",
    ["Timeout (seconds)"] = "Délai d'expiration (secondes)",
    ["Manual Reset"] = "Réinitialisation manuelle",
    ["Reset inspect state now"] = "Réinitialiser l'état d'inspection maintenant",
    ["Inspect state manually reset."] = "État d'inspection réinitialisé manuellement.",
    ["NotifyInspect hook: %s\nInspectFrame hook: %s"] = "Accroche sur NotifyInspect : %s\nAccroche sur InspectFrame : %s",
    ["|cff66ff66active|r"] = "|cff66ff66actif|r",
    ["|cffff8800waiting|r"] = "|cffff8800en attente|r",
    ["|cffff8800waiting for Blizzard_InspectUI|r"] = "|cffff8800en attente de Blizzard_InspectUI|r",
    ["|cffaaaaaaWhat the fix does: tracks active inspects with a timestamp, repaints late-arriving item data, re-requests an all-empty inspect once, and calls ClearInspectPlayer() on close + on timeout. Prevents a stuck state from blocking all subsequent inspects.|r"] = "|cffaaaaaaCe que fait le correctif : suit les inspections actives avec un horodatage, redessine les données d'objets arrivées en retard, relance une fois une inspection entièrement vide, et appelle ClearInspectPlayer() à la fermeture et à l'expiration. Empêche un état bloqué d'interdire toutes les inspections suivantes.|r",
    ["Auto-retry empty inspects"] = "Relancer les inspections vides",
    ["After the server answers, the item slots are repainted again shortly after (data often arrives late). If the window is still completely empty, the inspect is automatically requested one more time."] = "Après la réponse du serveur, les emplacements d'objets sont redessinés peu après (les données arrivent souvent en retard). Si la fenêtre est toujours entièrement vide, l'inspection est relancée une fois.",
    ["|cffaaaaaaStatus: %s|r"] = "|cffaaaaaaÉtat : %s|r",
    ["|cff66ff66Hook active|r"] = "|cff66ff66Accroche active|r",

    -- Correctifs divers
    ["LFG Browse Nil Fix"] = "Correctif de la recherche de groupe",
    ["Catches Lua errors in the Anniversary Group Finder (LFGBrowseSearchEntry_Update with stale resultIDs). Prevents chat spam and broken browse lists."] = "Intercepte les erreurs Lua du recherche de groupe d'Anniversaire (LFGBrowseSearchEntry_Update avec des identifiants périmés). Évite le spam dans la discussion et les listes cassées.",
    ["|cffffff00[VuloClassicUI]|r Blizzard LFG browse error caught (stale entry skipped)."] = "|cffffff00[VuloClassicUI]|r Erreur de recherche de groupe interceptée (entrée périmée ignorée).",
    ["Chat message on first error"] = "Message dans la discussion à la première erreur",
    ["Shows a brief message once per session in chat when an LFG browse error was caught."] = "Affiche un bref message une fois par session lorsqu'une erreur de recherche de groupe a été interceptée.",
    ["This fix wraps Blizzard's |cffffffffLFGBrowseSearchEntry_Update|r function in a protected call (xpcall). When the entry crashes due to a stale resultID (\"searchResultInfo nil\"), the error is swallowed — Blizzard's next refresh automatically cleans up the list entry."] = "Ce correctif enveloppe la fonction |cffffffffLFGBrowseSearchEntry_Update|r de Blizzard dans un appel protégé (xpcall). Quand l'entrée échoue à cause d'un identifiant périmé (« searchResultInfo nil »), l'erreur est absorbée — l'actualisation suivante de Blizzard nettoie automatiquement la liste.",
    ["waiting for Blizzard_GroupFinder_VanillaStyle"] = "en attente de Blizzard_GroupFinder_VanillaStyle",
    ["Guild News Nil Fix"] = "Correctif des nouvelles de guilde",
    ["Catches Lua errors in guild news entries (typically \"formatString\" or \"GuildUtil\") and replaces broken entries with a fallback text instead of letting the whole panel break."] = "Intercepte les erreurs Lua des entrées de nouvelles de guilde (typiquement « formatString » ou « GuildUtil ») et remplace les entrées défectueuses par un texte de repli au lieu de casser tout le panneau.",
    ["|cffff8080Invalid guild news entry|r"] = "|cffff8080Entrée de nouvelles de guilde invalide|r",
    ["|cffffff00[VuloClassicUI]|r Blizzard guild news error caught (fallback applied)."] = "|cffffff00[VuloClassicUI]|r Erreur de nouvelles de guilde interceptée (texte de repli appliqué).",
    ["Shows a brief message once per session in chat when a guild news error was caught."] = "Affiche un bref message une fois par session lorsqu'une erreur de nouvelles de guilde a été interceptée.",
    ["This fix wraps Blizzard's |cffffffffGuildNewsButton_SetNews|r function in a protected call (xpcall). When an entry throws a known error (\"formatString\" or \"GuildUtil\"), the entry is replaced with a fallback text \"Invalid guild news entry\" — the panel remains usable."] = "Ce correctif enveloppe la fonction |cffffffffGuildNewsButton_SetNews|r de Blizzard dans un appel protégé (xpcall). Quand une entrée déclenche une erreur connue (« formatString » ou « GuildUtil »), elle est remplacée par le texte de repli « Entrée de nouvelles de guilde invalide » — le panneau reste utilisable.",
    ["waiting for Blizzard_Communities"] = "en attente de Blizzard_Communities",
    ["Auction Price Fix"] = "Correctif des prix à l'hôtel des ventes",
    ["Fixes a nil error in the German auction house UI (PriceDropdown not defined)."] = "Corrige une erreur nil dans l'interface allemande de l'hôtel des ventes (PriceDropdown non défini).",
    ["This fix addresses a known bug in the German WoW localization: the auction house UI references a \"PriceDropdown\" element that was never defined, which causes Lua errors when opening the auction house."] = "Ce correctif traite un bogue connu de la localisation allemande de WoW : l'interface de l'hôtel des ventes fait référence à un élément « PriceDropdown » jamais défini, ce qui provoque des erreurs Lua à l'ouverture.",
    ["|cffaaaaaaCurrent locale: %s|r"] = "|cffaaaaaaLangue actuelle : %s|r",
    ["|cffaaaaaaThe fix only applies on German clients (deDE). On other languages the module is inactive.|r"] = "|cffaaaaaaLe correctif ne s'applique qu'aux clients allemands (deDE). Dans les autres langues, le module est inactif.|r",
    ["|cff66ff66applied|r"] = "|cff66ff66appliqué|r",
    ["skipped (deDE-only)"] = "ignoré (deDE uniquement)",
    ["not applied"] = "non appliqué",

