    -- Bijoux
    ["Trinkets"] = "Bijoux",
    ["Two trinket slots on screen with cooldown display, dropdown selection and auto-queue."] = "Deux emplacements de bijou à l'écran, avec affichage des recharges, liste de sélection et file automatique.",
    ["|cffaaaaaaTwo trinket slots with cooldown, dropdown selection and auto-queue.|nLeft click = use, right click = dropdown.|r"] = "|cffaaaaaaDeux emplacements de bijou avec recharge, liste de sélection et file automatique.|nClic gauche = utiliser, clic droit = liste.|r",
    ["Show frame"] = "Afficher la fenêtre",
    ["Hides or shows the two trinket slots. Auto-queue continues to run while hidden."] = "Masque ou affiche les deux emplacements de bijou. La file automatique continue de fonctionner même masquée.",
    ["Position locked"] = "Position verrouillée",
    ["If on, the frame cannot be accidentally moved."] = "Si activé, la fenêtre ne peut pas être déplacée par inadvertance.",
    ["Size"] = "Taille",
    ["Scales the trinket slots."] = "Met à l'échelle les emplacements de bijou.",

    -- Habillage sombre
    ["Character Panel"] = "Panneau du personnage",
    ["Dark Skin"] = "Habillage sombre",
    ["The dark look of the UI in one place: a built-in dark skin for action buttons and WeakAuras icons, plus an optional Dark Mode that darkens Blizzard's default frames, minimap and bars."] = "Tout l'aspect sombre de l'interface au même endroit : un habillage sombre intégré pour les boutons d'action et les icônes WeakAuras, plus un mode sombre facultatif qui assombrit les fenêtres, la minicarte et les barres de Blizzard.",
    ["|cffaaaaaaThe dark look of the UI in one place: a built-in skin for action buttons and WeakAuras icons, plus an optional Dark Mode that re-tints Blizzard's default frames.|r"] = "|cffaaaaaaTout l'aspect sombre de l'interface au même endroit : un habillage intégré pour les boutons d'action et les icônes WeakAuras, plus un mode sombre facultatif qui recolore les fenêtres de Blizzard.|r",
    ["The dark action-bar button skin."] = "L'habillage sombre des boutons de barre d'action.",
    ["Enable Dark Mode"] = "Activer le mode sombre",
    ["Re-tints Blizzard's default frames, minimap and action-bar artwork to a dark tone. Off by default."] = "Recolore les fenêtres, la minicarte et les décors de barre d'action de Blizzard dans une teinte sombre. Désactivé par défaut.",
    ["|cffaaaaaaOptional: darkens and desaturates Blizzard's default artwork — unit frames, minimap and action bars — to a neutral dark tone. Reversible: turn it off and the gold look returns.|r"] = "|cffaaaaaaFacultatif : assombrit et désature les décors de Blizzard — fenêtres d'unité, minicarte et barres d'action — vers une teinte sombre neutre. Réversible : désactivez l'option et l'aspect doré revient.|r",
    ["Action Bars"] = "Barres d'action",
    ["Skin the action bars"] = "Habiller les barres d'action",
    ["Bar style"] = "Style de barre",
    ["Bar icon size"] = "Taille des icônes de barre",
    ["How much of the button the icon fills in Shadow style. Higher = bigger icons with a thinner rim."] = "Proportion du bouton occupée par l'icône dans le style Ombre. Plus la valeur est élevée, plus les icônes sont grandes et la bordure fine.",
    ["WeakAuras Icons"] = "Icônes WeakAuras",
    ["Skin WeakAuras icons"] = "Habiller les icônes WeakAuras",
    ["WeakAuras style"] = "Style WeakAuras",
    ["Style for WeakAuras icons, independent of the action bars."] = "Style des icônes WeakAuras, indépendant des barres d'action.",
    ["Hide WeakAuras' own border"] = "Masquer la bordure propre de WeakAuras",
    ["Hides the light border WeakAuras draws on icons, so only our dark rim shows. /reload to fully restore it."] = "Masque la bordure claire que WeakAuras dessine sur les icônes, afin que seule notre bordure sombre reste visible. Un /reload la rétablit entièrement.",
    ["Pick how the action buttons look. Rounded/Circle use an icon mask; Minimal is just the cropped icon."] = "Choisissez l'aspect des boutons d'action. Arrondi et Cercle utilisent un masque d'icône ; Minimal n'affiche que l'icône rognée.",
    ["Shadow (dark rounded rim)"] = "Ombre (bordure arrondie sombre)",
    ["Rounded icon (masked corners)"] = "Icône arrondie (coins masqués)",
    ["Square (black edge)"] = "Carré (bord noir)",
    ["Square (accent edge)"] = "Carré (bord accentué)",
    ["Circle"] = "Cercle",
    ["Minimal (icon only)"] = "Minimal (icône seule)",
    ["Minimal Dark (darkened Blizzard border)"] = "Minimal sombre (bordure Blizzard assombrie)",
    ["Also skin pet & stance buttons"] = "Habiller aussi les boutons de familier et de posture",

    -- Panneau du personnage
    ["Enhances the character panel: iLvL per slot, socket display, shortened enchant text."] = "Améliore le panneau du personnage : niveau d'objet par emplacement, affichage des châsses, texte d'enchantement raccourci.",
    ["Show item level per slot"] = "Afficher le niveau d'objet par emplacement",
    ["Show average item level"] = "Afficher le niveau d'objet moyen",
    ["Show sockets"] = "Afficher les châsses",
    ["Shorten enchant text (DE/EN)"] = "Raccourcir le texte d'enchantement (DE/EN)",
    ["Example: 'Stamina' -> 'Stam', 'Ausdauer' -> 'Ausd'."] = "Exemple : « Endurance » → « End. », « Stamina » → « Stam ».",
    ["Treat rings as enchantable"] = "Considérer les anneaux comme enchantables",
    ["Also shows enchant text on rings (TBC: some professions can enchant rings). /reload required."] = "Affiche également le texte d'enchantement sur les anneaux (en TBC, certains métiers peuvent enchanter les anneaux). Nécessite /reload.",
    ["Text Size"] = "Taille du texte",
    ["Item Level Text Size"] = "Taille du texte de niveau d'objet",
    ["Font size of the item level number on each item slot. Takes effect immediately when the character panel is open."] = "Taille de police du niveau d'objet sur chaque emplacement. Effet immédiat lorsque le panneau du personnage est ouvert.",
    ["Note: Some changes only take full effect after /reload, since the character panel is hooked on load."] = "Remarque : certains changements ne prennent pleinement effet qu'après un /reload, car le panneau du personnage est accroché au chargement.",
    ["|cffff0000No Ench|r"] = "|cffff0000Sans ench.|r",
    ["|c%siLvL - %d|r"] = "|c%sNiv. obj. - %d|r",
    ["Mark empty sockets"] = "Marquer les châsses vides",
    ["Adds a red ring around item sockets that have no gem."] = "Ajoute un anneau rouge autour des châsses d'objet sans gemme.",
    ["Text shadow (instead of outline)"] = "Ombre du texte (au lieu du contour)",
    ["Cleaner text with a drop shadow instead of a thick outline."] = "Texte plus net, avec une ombre portée au lieu d'un contour épais.",

    -- Suivi de l'or
    ["Gold Tracker"] = "Suivi de l'or",
    ["Shows in the backpack gold tooltip how much gold has been gained or spent since the last reset. Per-char persistent."] = "Affiche dans l'infobulle d'or du sac à dos combien d'or a été gagné ou dépensé depuis la dernière réinitialisation. Conservé par personnage.",
    ["Gold Tracker reset|r. Start = "] = "Suivi de l'or réinitialisé|r. Départ = ",
    ["Gold Balance|r"] = "Bilan de l'or|r",
    ["Gained:|r"] = "Gagné :|r",
    ["Spent:|r"] = "Dépensé :|r",
    ["|cffffffffNet:|r"] = "|cffffffffNet :|r",
    ["Start:|r"] = "Départ :|r",
    ["Now:|r"] = "Actuel :|r",
    ["Reset with /vcui goldreset|r"] = "Réinitialiser avec /vcui goldreset|r",
    ["|cffaaaaaaShows in the backpack gold tooltip the balance since the last manual reset:|n  - |cff44ff44Gained|r (quests, loot, vendor sales, mail)|n  - |cffff4444Spent|r (repair, vendor buy, mail cost)|n  - |cffffffffNet|r (+/- since reset)|n|nValues are |cffffffffper-char persistent|r across /reload and logout.|nOffline gold (AH mail, trade) is not counted.|n|nReset: button below or |cffffff00/vcui goldreset|r.|r"] = "|cffaaaaaaAffiche dans l'infobulle d'or du sac à dos le bilan depuis la dernière réinitialisation manuelle :|n  - |cff44ff44Gagné|r (quêtes, butin, ventes aux marchands, courrier)|n  - |cffff4444Dépensé|r (réparations, achats, frais de courrier)|n  - |cffffffffNet|r (+/- depuis la réinitialisation)|n|nLes valeurs sont |cffffffffconservées par personnage|r après un /reload et une déconnexion.|nL'or reçu hors ligne (courrier de l'hôtel des ventes, échanges) n'est pas compté.|n|nRéinitialisation : le bouton ci-dessous ou |cffffff00/vcui goldreset|r.|r",
    ["Reset session"] = "Réinitialiser la session",

    -- Spécifique à la classe
    ["Class Specific"] = "Spécifique à la classe",
    ["|cffaaaaaaVampiric Touch mana tracker — shows live how much mana you've given to the group (5% of shadow damage per tick, per mana user).|n|cffffffffReset automatically on combat start.|r|r"] = "|cffaaaaaaSuivi de mana de Toucher vampirique — affiche en direct la quantité de mana rendue au groupe (5 % par salve des dégâts d'Ombre, pour chaque utilisateur de mana).|n|cffffffffRéinitialisé automatiquement au début du combat.|r|r",
    ["|cffff8800These tools are only active while playing a Priest.|r"] = "|cffff8800Ces outils ne sont actifs que sur un prêtre.|r",
    ["No tools yet"] = "Aucun outil pour l'instant",
    ["|cffaaaaaaNo class-specific tools for this class yet. Got an idea? Let me know!|r"] = "|cffaaaaaaAucun outil spécifique à cette classe pour l'instant. Une idée ? Faites-la moi savoir !|r",
    ["|cff9b6cffVT Mana:|r %d"] = "|cff9b6cffMana TV :|r %d",
    ["|cff9b6cffVT Mana:|r 0"] = "|cff9b6cffMana TV :|r 0",
    ["Vampiric Touch: %d mana given to the group."] = "Toucher vampirique : %d points de mana rendus au groupe.",
    ["|cffffffffVT MANA|r"] = "|cffffffffMANA TV|r",
    ["VT mana frame: x=%.0f, y=%.0f"] = "Fenêtre de mana TV : x=%.0f, y=%.0f",
    ["VT mana mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "Déplacement du mana TV actif. |cff9b6cffGlissez|r ou utilisez les |cff9b6cfftouches fléchées|r (MAJ = 5 px).",
    ["VT mana mover disabled."] = "Déplacement du mana TV désactivé.",
    ["Print to chat at combat end"] = "Afficher dans la discussion à la fin du combat",
    ["Writes a summary in chat after each fight."] = "Écrit un résumé dans la discussion après chaque combat.",
    ["Reset manually"] = "Réinitialiser manuellement",
    ["VT mana reset."] = "Mana TV réinitialisé.",

    -- Suivi des DoT
    ["Bars"] = "Barres",
    ["Icons"] = "Icônes",
    ["Shadow Word: Pain"] = "Mot de l'ombre : Douleur",
    ["Vampiric Touch"] = "Toucher vampirique",
    ["Devouring Plague"] = "Peste dévorante",
    ["Warning (seconds left)"] = "Avertissement (secondes restantes)",
    ["Bar width"] = "Largeur de barre",
    ["Bar height"] = "Hauteur de barre",
    ["Spacing"] = "Espacement",
    ["Color the timer text"] = "Colorer le texte du minuteur",
    ["Show recast gain %"] = "Afficher le gain de relancement en %",
    ["Shows how much harder a fresh cast would hit right now (e.g. +12% with a spell power proc up). Negative values mean the running DoT snapshotted stronger — keep it."] = "Indique de combien un nouveau lancement frapperait plus fort maintenant (p. ex. +12 % avec une amélioration de puissance des sorts active). Une valeur négative signifie que le DoT en cours a figé une valeur plus forte — mieux vaut le laisser.",
    ["DoT Tracker"] = "Suivi des DoT",
    ["|cffaaaaaaTracks your DoTs on the target. |cff44ff44Green|r = a buff is up that makes it hit harder if you recast now (TBC snapshot); |cffff4444red|r = about to expire.|r"] = "|cffaaaaaaSuit vos DoT sur la cible. |cff44ff44Vert|r = une amélioration est active et rendrait un relancement plus puissant (instantané TBC) ; |cffff4444rouge|r = expire bientôt.|r",
    ["|cffff8800Only active while playing a %s.|r"] = "|cffff8800Actif uniquement sur un %s.|r",
    ["|cffaaaaaaTracks your Warlock DoTs (Corruption, Curse of Agony, Unstable Affliction, Siphon Life, Immolate, Curse of Doom) on the target, with the same recast-snapshot readout as the Priest tracker.|r"] = "|cffaaaaaaSuit vos DoT de démoniste (Corruption, Malédiction d'agonie, Affliction instable, Siphon de vie, Immolation, Malédiction funeste) sur la cible, avec le même affichage d'instantané de relancement que le suivi du prêtre.|r",
