    ["|cffffffffDOTS|r"] = "|cffffffffDOT|r",
    ["Shadow DoTs: x=%.0f, y=%.0f"] = "DoT Ombre : x=%.0f, y=%.0f",
    ["Shadow DoTs mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "Déplacement des DoT Ombre actif. |cff9b6cffGlissez|r ou utilisez les |cff9b6cfftouches fléchées|r (MAJ = 5 px).",
    ["Shadow DoTs mover disabled."] = "Déplacement des DoT Ombre désactivé.",

    -- Minicarte
    ["|cffaaaaaaA modern round minimap with a beveled ring, zone text and clock in a slim pill. Zoom with the mouse wheel. |cffffffffShift+drag the map|r to move it — or use Unlock / the addon's own Edit Mode (/vedit). Blizzard's Edit Mode does not manage this map.|r"] = "|cffaaaaaaUne minicarte ronde et moderne, avec un anneau biseauté, le nom de la zone et l'horloge dans une pastille fine. Zoom à la molette. |cffffffffMaj + glisser la carte|r pour la déplacer — ou utilisez Déverrouiller / le mode Édition de l'add-on (/vedit). Le mode Édition de Blizzard ne gère pas cette carte.|r",
    ["|cffffffffMINIMAP|r"] = "|cffffffffMINICARTE|r",
    ["Minimap: x=%.0f, y=%.0f"] = "Minicarte : x=%.0f, y=%.0f",
    ["Minimap mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "Déplacement de la minicarte actif. |cff9b6cffGlissez|r ou utilisez les |cff9b6cfftouches fléchées|r (MAJ = 5 px).",
    ["Minimap module disabled — /reload restores the default layout completely."] = "Module de minicarte désactivé — un /reload rétablit entièrement la disposition par défaut.",
