    ["Restyles the guild and communities window to the same dark look. Turning it off needs a /reload."] = "Applique le même aspect sombre à la fenêtre de guilde et de communautés. La désactivation nécessite un /reload.",
    ["Custom ring color"] = "Couleur d'anneau personnalisée",
    ["A thin colored line around the dark ring (round shape only)."] = "Une fine ligne colorée autour de l'anneau sombre (forme ronde uniquement).",
    ["Zone panel"] = "Panneau de zone",
