    ["To the left"] = "Vers la gauche",
    ["To the right"] = "Vers la droite",
    ["Open flyout in combat"] = "Ouvrir le sélecteur en combat",
    ["Tooltip with cooldown on hover"] = "Infobulle avec recharge au survol",
    ["Hovering a totem slot or a picker icon shows the totem name and its remaining cooldown."] = "Survoler un emplacement de totem ou une icône du sélecteur affiche le nom du totem et sa recharge restante.",
    ["Off = hovering a slot never opens the totem picker while you are fighting (clicks still cast). The picker now also closes itself on mouse-out and after every cast, even in combat."] = "Désactivé = survoler un emplacement n'ouvre jamais le sélecteur de totems pendant un combat (les clics lancent toujours le totem). Le sélecteur se referme également de lui-même lorsque la souris le quitte et après chaque lancement, même en combat.",
    ["Earth"] = "Terre",
