    ["Search"] = "Rechercher",
    ["Sort tab"] = "Trier l'onglet",
    ["Sorts the current tab (mode from the bag options). Needs withdraw rights on the tab."] = "Trie l'onglet actuel (mode défini dans les options des sacs). Nécessite le droit de retrait sur l'onglet.",
    ["Money log"] = "Journal de l'argent",
    ["Shows who deposited or withdrew guild money."] = "Indique qui a déposé ou retiré de l'argent de la guilde.",
    ["No transactions yet."] = "Aucune transaction pour l'instant.",
    ["Show your bank in a matching window when you visit a banker. Off = the default bank window."] = "Affiche votre banque dans une fenêtre assortie lorsque vous visitez un banquier. Désactivé = la fenêtre de banque par défaut.",
    ["Bank window scale"] = "Échelle de la fenêtre de banque",
