    ["Sort bank"] = "Trier la banque",
    ["Click to show or hide this bag."] = "Cliquez pour afficher ou masquer ce sac.",
    ["Left-click: show or hide."] = "Clic gauche : afficher ou masquer.",
    ["Right-click: pick up or equip the bag."] = "Clic droit : prendre ou équiper le sac.",
    ["Right-click: buy this bag slot."] = "Clic droit : acheter cet emplacement de sac.",
    ["Show item levels"] = "Afficher les niveaux d'objet",
    ["Shows the item level on weapons and armor."] = "Affiche le niveau d'objet sur les armes et les armures.",
    ["Faction/Server Gold:|r"] = "Or par faction / royaume :|r",
    ["Account total:|r"] = "Total du compte :|r",
